sp_widget.client_script:
// Client Script (Handle Redirect & UI)
(function() {
    api.controller = function($scope, $timeout, $window) {
        $scope.loading = true;

        $timeout(function() {
            $scope.loading = false;
        }, 1000);

        $scope.redirect = function(page) {
            if (page) {
                $window.location.href = page;
            }
        };
    };
})();

sp_widget.script:
// Service Portal Widget: Main Homepage Widget

// Server Script (Fetch User Role from ServiceNow)
(function() {
    data.userRole = gs.getUser().getRoles(); // Fetch roles

    data.pages = {
        hr: "/hr_dashboard_hub",
        manager: "/manager_approval",
        home: "/onboarding_offboarding_homepage"
    };

    if (data.userRole.includes("admin")) {
        data.redirectPage = data.pages.manager;
    } else if (data.userRole.includes("admin")) {
        data.redirectPage = data.pages.employee;
    } else {
        data.redirectPage = data.pages.admin; // Default to HR dashboard
    }
})();
